mapper.update:
update group_member
set join_status = 'PENDING',
    update_time = CURRENT_TIMESTAMP()
where group_id = #{groupId}
  and user_id = #{userId}
  and join_status = 'REJECTED'

mapper.delete:
delete from group_member
where group_id = #{groupId}
  and user_id = #{userId}
  and join_status = 'APPROVED'
  and role <> 'ROOT'
